export { DeleteNotSupportedError, EditError, emptyFs, FILE_SYSTEM_SCAN_LIMIT, FileNotFoundError, hostFs, InvalidGrepPatternError, isFileNotFoundError, NoMountError, childOverlayFs, overlayFs, PathError, ReadOnlyMountError, strReplaceOnFileSystem, tempFs, unionFs, WriteFailedError, } from "./filesystem.js";
export { defineHook } from "./hooks.js";
