export { cursorAccountServersHasMixedWildcard, DEFAULT_MODEL, DIRECT_TOOL_CALL_CHANNEL_ID, HttpSessionAdmitError, isCursorAccountTransport, isPeerConnectionTransport, isSymbolicConnectionTransport, isToolEffect, MAX_RUNNING_TURNS_LIMIT, normalizeConnectionEffects, normalizeConnectionTools, normalizeCursorAccountServers, supportsKvCas, } from "./types.js";
/**
 * Runtime config for an agent — authored at `agent/agent.ts` (the root
 * agent) or `agent/subagents/<id>/agent.ts` (a subagent).
 */
export function defineAgent(config) {
    return brandDefinition("agent", config);
}
/**
 * Programmatic instructions — authored at `agent/instructions.ts` when the
 * system prompt needs to be generated rather than written as markdown.
 */
export function defineInstructions(config) {
    return brandDefinition("instructions", config);
}
/**
 * Discover and serve one or more agents over HTTP.
 *
 * Defaults to multi-agent layout: each agent is mounted under `/<slug>/v1/*`
 * and `/<slug>/playground`, with an index at `/`.
 *
 * - Given a directory that is itself an agent project, mounts it under its
 *   directory name as the slug.
 * - Given a directory whose immediate children are agent projects, mounts
 *   each under its directory name.
 * - Pass `mode: "single"` (or a {@link Project}) for the unslugged
 *   `/v1/*` surface.
 *
 * The built-in session channel lives under `/v1/session*`, custom channels
 * under `/v1/channels/<id>`, plus `/v1/health` and `/v1/info`. Schedules run
 * on their cron cadence unless dev mode or `schedules: false` disables them.
 */
export async function serve(projectOrDir, options = {}) {
    if ("otel" in options) {
        throw new Error("serve({ otel }) is removed. See https://cursor.com/docs/bdk/guides/opentelemetry#migrating-from-serve-otel.");
    }
    const { discovery, mode, ...serveOptions } = options;
    // Programmatic embedders get the same authored-TypeScript loading as the
    // CLI (idempotent; the bin registers earlier, source runs are a no-op).
    await registerAuthoredModuleLoaders();
    // Set before discovery so channel factories (constructed at import time) can
    // relax dev-only defaults — e.g. the GitHub channel accepting unsigned
    // loopback-forwarded deliveries. No-op outside dev.
    setDevMode(serveOptions.dev === true);
    if (typeof projectOrDir !== "string") {
        return startServer([{ slug: "", project: unwrapProject(projectOrDir) }], serveOptions);
    }
    const mounts = await resolveAgentMounts(projectOrDir, {
        ...discovery,
        ...(mode === undefined ? {} : { mode }),
    });
    return startServer(mounts, serveOptions);
}
